
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_sregtm_v3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_sregtm_v3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.654413534465195e+00, -4.561749161344110e+00, -4.431970727919493e+00, -4.252336982392235e+00, -4.007865947636748e+00, -3.683143479839577e+00, -3.266574092552859e+00, -2.757916650109772e+00, -2.177597928805852e+00, -1.568756632460756e+00, -1.008950186118605e+00, -7.055122159441827e-01, -6.035893215851421e-01, -5.115255529158645e-01, -3.671217862282594e-01, -2.263298827650281e-01, -1.197996627044193e-01, -5.402432676660958e-02, -2.012346880040028e-02, -5.340788267823797e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


